(async () => {
  // Expects: function sparql(queryString) and temp_nodes in scope
  const PREFIX = `
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX d3f:  <http://d3fend.mitre.org/ontologies/d3fend.owl#>
`.trim();
  const D3F_BASE = 'http://d3fend.mitre.org/ontologies/d3fend.owl#';

  const baseLabel = (s) => {
    const t = String(s ?? '');
    if (t.startsWith('* ')) return t.slice(2);
    if (t.startsWith('*')) return t.slice(1);
    return t;
  };
  const isNote = (n) => n && n.type === 'note-node';
  const raw = (cls) => (typeof cls === 'string' && cls.length ? cls : null);
  const toIRI = (cls) => {
    if (!cls) return null;
    if (cls.startsWith('d3f:')) return D3F_BASE + cls.slice(4);
    if (cls.startsWith('http://') || cls.startsWith('https://')) return cls;
    return null;
  };
  const toPrefixed = (cls) => {
    if (!cls) return '';
    if (cls.startsWith('d3f:')) return cls;
    if (cls.startsWith('http://') || cls.startsWith('https://')) {
      if (cls.startsWith(D3F_BASE)) return 'd3f:' + cls.slice(D3F_BASE.length);
      return cls;
    }
    return String(cls);
  };
  const inValues = (cls) => {
    if (!cls) return null;
    if (cls.startsWith('http://') || cls.startsWith('https://')) return `<${cls}>`;
    return cls;
  };

  const classes = [];
  for (const n of temp_nodes) {
    if (isNote(n)) continue;
    const c = raw(n?.data?.d3f_class);
    if (c) classes.push(c);
  }
  const uniq = [...new Set(classes)];
  if (uniq.length === 0) return;
  const values = uniq.map(inValues).filter(Boolean).join(' ');
  const query = `${PREFIX}
SELECT ?cls WHERE {
  VALUES ?cls { ${values} }
  ?cls rdfs:subClassOf* d3f:D3FENDCore .
}`;

  let bindings = [];
  try {
    bindings = await sparql(query);
  } catch (e) {
    console.warn('SPARQL error in class validation:', e);
    bindings = [];
  }

  const exists = new Set();
  if (Array.isArray(bindings)) {
    for (const row of bindings) {
      const term = row.get ? row.get('cls') : (row.cls ?? row['?cls']);
      const iri = term?.value ?? term;
      if (iri) exists.add(String(iri));
    }
  }

  for (const node of temp_nodes) {
    if (isNote(node)) continue;
    const cls = raw(node?.data?.d3f_class);
    if (!cls) continue;
    const iri = toIRI(cls);
    const ok = exists.has(iri);
    const labelText = toPrefixed(cls);
    node.data.label = ok ? labelText : `*${labelText}`;
  }
})()
